-- PT121-S1-Q11. Batch 08.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch08$PT121-S1-Q11$batch08$ AND q.stimulus=$batch08$Students asked by a psychologist to tell a lie before discussion groups vastly overestimated how many people in the discussion groups could tell they were lying. Other research has found that when volleyball players perform unusually poorly on the court, teammates notice this far less often than the players expect. Finally, in one research experiment a student wearing a funny T-shirt entered a room full of people. Questioning revealed that only a small fraction of the people in the room noticed the shirt, contrary to the student’s expectations.$batch08$ AND q.prompt=$batch08$Which one of the following is best illustrated by the statements above?$batch08$ AND q.correct_choice=$batch08$E$batch08$) THEN RAISE EXCEPTION 'Question changed: PT121-S1-Q11'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch08$PT121-S1-Q11$batch08$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT121-S1-Q11'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch08$PT121-S1-Q11$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch08$Statements$batch08$, $batch08$Students telling a lie overestimated how many people noticed. Volleyball players expect teammates to notice a bad game far more than they do. A student in a funny T-shirt expected more people to notice it than did.$batch08$), (1, $batch08$Evaluate$batch08$, $batch08$Pause and infer. All three examples have the same shape. A person expects to be noticed, and fewer people actually notice. The thread is the gap between how much we *think* others notice us and how much they really do.$batch08$), (2, $batch08$Goal$batch08$, $batch08$People overestimate how much others notice them.$batch08$)) v(position,label,body) WHERE q.qid=$batch08$PT121-S1-Q11$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch08$A$batch08$, $batch08$None of the examples measure how aware people are of their own appearance or behavior.$batch08$), ($batch08$B$batch08$, $batch08$Some people did notice, and in the lying study we only know people overestimated how many could tell. B drops the key part, the mistaken expectation.$batch08$), ($batch08$C$batch08$, $batch08$This is the most popular wrong answer. It flips the point of view. The examples are about what people expect others to notice *about them*, not about how observant people think they themselves are.$batch08$), ($batch08$D$batch08$, $batch08$"Only if specifically highlighted" is a strong condition nothing supports.$batch08$), ($batch08$E$batch08$, $batch08$Liar, player, T-shirt: each expected more attention than they got.$batch08$)) v(letter,body) WHERE q.qid=$batch08$PT121-S1-Q11$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
